<script setup lang="ts">
import { ArrowLeft, Landmark } from 'lucide-vue-next'
import { createEmployeeLoans, loanRepayments, loanSummary, type EmployeePortalLoan, type EmployeeLoanPayment } from '~/utils/employeeLoans'

const loans = createEmployeeLoans()
const { profile } = useEmployeePortal()
const detailsOpen = ref(false)
const selectedLoan = ref<EmployeePortalLoan | null>(null)
const selectedPayment = ref<(EmployeeLoanPayment & { balanceAfter: number }) | null>(null)
const summary = computed(() => selectedLoan.value ? loanSummary(selectedLoan.value) : null)
const repayments = computed(() => selectedLoan.value ? loanRepayments(selectedLoan.value) : [])
const totalOutstanding = computed(() => loans.reduce((sum, loan) => sum + loanSummary(loan).outstanding, 0))
const activeCount = computed(() => loans.filter(loan => loanSummary(loan).outstanding > 0).length)
const totalInstallments = computed(() => loans.filter(loan => loanSummary(loan).outstanding > 0).reduce((sum, loan) => sum + Math.min(loan.installment, loanSummary(loan).outstanding), 0))
const money = (value: number) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' }).format(value)
const date = (value: string | null) => value ? new Date(`${value}T12:00:00`).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }) : 'No further payments'
const openLoan = (loan: EmployeePortalLoan) => { selectedLoan.value = loan; selectedPayment.value = null; detailsOpen.value = true }
</script>

<template>
  <section class="employee-loans">
    <div class="loan-stats"><article><span>Active Loans</span><strong>{{ activeCount }}</strong></article><article><span>Outstanding Balance</span><strong>{{ money(totalOutstanding) }}</strong></article><article><span>Monthly Installments</span><strong>{{ money(totalInstallments) }}</strong></article></div>
    <article class="loan-card"><header><div><h2><Landmark :size="18" />Loan History</h2><p>View your own loan balances and recorded repayments.</p></div><span class="read-only">Read-only</span></header><p class="mobile-table-hint">Tap a loan row for terms, due dates and repayment history.</p>
      <div class="table-scroll" role="region" aria-label="Employee loans" tabindex="0"><table class="mobile-compact-table"><thead><tr><th scope="col">Loan</th><th scope="col" class="mobile-hide amount">Principal</th><th scope="col" class="mobile-hide amount">Paid</th><th scope="col" class="amount">Outstanding</th><th scope="col" class="amount">Installment</th><th scope="col">Status</th></tr></thead><tbody><tr v-for="loan in loans" :key="loan.id" class="record-row" @click="openLoan(loan)"><th scope="row"><button type="button" class="row-open-button" :aria-label="`Open ${loan.type} ${loan.id}`" @click.stop="openLoan(loan)">{{ loan.type }}</button><small class="mobile-hide">{{ loan.id }}</small></th><td class="mobile-hide amount">{{ money(loan.principal) }}</td><td class="mobile-hide amount">{{ money(loanSummary(loan).paid) }}</td><td class="amount balance">{{ money(loanSummary(loan).outstanding) }}</td><td class="amount">{{ money(loanSummary(loan).outstanding ? Math.min(loan.installment, loanSummary(loan).outstanding) : 0) }}<small>{{ loanSummary(loan).outstanding ? loan.frequency : 'Completed' }}</small></td><td><span class="loan-status" :class="{ paid: loanSummary(loan).outstanding === 0 }">{{ loanSummary(loan).status }}</span></td></tr></tbody></table></div>
    </article>
    <p class="source-note">Loan figures are fictional frontend records, not verified HR/finance data. Bank-transfer repayments are not linked to payslip deductions. Contact HR or Finance for corrections or payment instructions.</p>

    <EmployeeRecordDialog v-model="detailsOpen" :title="selectedPayment ? 'Repayment Details' : 'Loan Details'" :subtitle="selectedLoan ? `${selectedLoan.type} · ${selectedLoan.id}` : ''">
      <template v-if="selectedLoan && summary">
        <template v-if="selectedPayment"><button type="button" class="back-to-loan" @click="selectedPayment = null"><ArrowLeft :size="16" />Back to loan</button><dl class="record-fields"><div><dt>Payment Reference</dt><dd>{{ selectedPayment.reference }}</dd></div><div><dt>Payment Date</dt><dd>{{ date(selectedPayment.date) }}</dd></div><div><dt>Amount Paid</dt><dd>{{ money(selectedPayment.amount) }}</dd></div><div><dt>Balance After Payment</dt><dd>{{ money(selectedPayment.balanceAfter) }}</dd></div><div><dt>Payment Method</dt><dd>{{ selectedPayment.method }}</dd></div><div><dt>Record Status</dt><dd>Recorded</dd></div><div class="wide"><dt>Remarks</dt><dd>{{ selectedPayment.remarks }}</dd></div></dl></template>
        <template v-else>
          <div class="loan-progress"><div><strong>{{ money(summary.outstanding) }} remaining</strong><span>{{ Math.round(summary.progress) }}% repaid</span></div><progress :value="summary.progress" max="100" aria-label="Loan repayment progress" /></div>
          <dl class="record-fields"><div><dt>Employee</dt><dd>{{ profile.name }} · {{ profile.employeeId }}</dd></div><div><dt>Status</dt><dd>{{ summary.status }}</dd></div><div><dt>Principal</dt><dd>{{ money(selectedLoan.principal) }}</dd></div><div><dt>Interest / Charges</dt><dd>{{ money(selectedLoan.interest) }}</dd></div><div><dt>Total Amount Due</dt><dd>{{ money(summary.totalDue) }}</dd></div><div><dt>Total Paid</dt><dd>{{ money(summary.paid) }}</dd></div><div><dt>Outstanding Balance</dt><dd>{{ money(summary.outstanding) }}</dd></div><div><dt>Scheduled Installment</dt><dd>{{ money(selectedLoan.installment) }} · {{ selectedLoan.frequency }}</dd></div><div><dt>Date Granted</dt><dd>{{ date(selectedLoan.grantedAt) }}</dd></div><div><dt>First Payment Date</dt><dd>{{ date(selectedLoan.firstPaymentAt) }}</dd></div><div><dt>Next Payment Due</dt><dd>{{ summary.outstanding ? date(selectedLoan.nextDueAt) : 'Fully paid — no payment due' }}</dd></div><div><dt>Repayment Method</dt><dd>{{ selectedLoan.method }}</dd></div><div class="wide"><dt>Remarks</dt><dd>{{ selectedLoan.remarks }}</dd></div></dl>
          <h3 class="repayment-heading">Repayment History</h3><p class="repayment-help">Tap a repayment row for its full details.</p><div class="table-scroll" role="region" aria-label="Loan repayment history" tabindex="0"><table class="mobile-compact-table"><thead><tr><th scope="col">Date</th><th scope="col" class="amount">Paid</th><th scope="col" class="amount">Balance</th><th scope="col">Reference</th></tr></thead><tbody><tr v-for="payment in repayments" :key="payment.id" class="record-row" @click="selectedPayment = payment"><th scope="row"><button type="button" class="row-open-button" :aria-label="`Open repayment ${payment.reference}`" @click.stop="selectedPayment = payment">{{ date(payment.date) }}</button></th><td class="amount">{{ money(payment.amount) }}</td><td class="amount">{{ money(payment.balanceAfter) }}</td><td>{{ payment.reference }}</td></tr><tr v-if="!repayments.length"><td colspan="4">No repayments recorded.</td></tr></tbody></table></div>
        </template>
        <p class="source-note">Frontend reference record only. This screen does not submit payments or change payroll deductions.</p>
      </template>
    </EmployeeRecordDialog>
  </section>
</template>

<style scoped>
.employee-loans { min-width: 0; }.loan-stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-bottom: 16px; }.loan-stats article { min-width: 0; padding: 18px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-card); box-shadow: var(--shadow); }.loan-stats span { display: block; font-size: 11px; color: var(--text-secondary); }.loan-stats strong { display: block; font-size: 23px; margin-top: 10px; color: var(--primary); overflow-wrap: anywhere; }.loan-card { min-width: 0; overflow: hidden; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-card); box-shadow: var(--shadow); }header { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px; padding: 18px; }h2 { display: flex; align-items: center; gap: 8px; font-size: 14px; margin: 0; }h2 svg { color: var(--primary); }header p { font-size: 11px; color: var(--text-secondary); margin: 6px 0 0; }.read-only { color: var(--text-muted); font-size: 10px; }.table-scroll { overflow-x: auto; }table { width: 100%; border-collapse: collapse; text-align: left; font-size: 11px; }th, td { padding: 13px 14px; border-bottom: 1px solid var(--border-soft); }thead th { font-weight: 500; color: var(--text-secondary); background: var(--bg-card-soft); }tbody th { font-weight: 500; }td { color: var(--text-secondary); }small { display: block; font-size: 10px; margin-top: 4px; color: var(--text-muted); }.amount { text-align: right; font-variant-numeric: tabular-nums; }.balance { color: var(--primary); font-weight: 600; }.loan-status { display: inline-block; padding: 5px 8px; border-radius: 5px; color: var(--primary); background: var(--primary-soft); font-size: 10px; }.loan-status.paid { color: var(--green); background: var(--green-soft); }.source-note { margin: 14px 0 0; font-size: 11px; color: var(--text-secondary); line-height: 1.8; }.loan-progress { padding: 14px; margin-bottom: 24px; border-radius: 10px; background: var(--primary-soft); }.loan-progress > div { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; margin-bottom: 10px; }.loan-progress strong { font-size: 14px; color: var(--primary); }.loan-progress span { font-size: 11px; color: var(--text-secondary); }progress { width: 100%; height: 9px; accent-color: var(--primary); }.repayment-heading { margin: 26px 0 6px; font-size: 14px; }.repayment-help { color: var(--text-secondary); font-size: 11px; margin: 0 0 12px; }.back-to-loan { display: inline-flex; align-items: center; gap: 7px; min-height: 44px; margin-bottom: 20px; padding: 8px 11px; border: 1px solid var(--border); border-radius: 8px; color: var(--primary); background: var(--primary-soft); }.table-scroll:focus-visible, .back-to-loan:focus-visible { outline: 2px solid var(--primary); outline-offset: -2px; }
@media(max-width: 850px) { .loan-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }.loan-stats article { padding: 13px; }.loan-stats article:last-child { grid-column: 1 / -1; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px; }.loan-stats strong { font-size: 20px; }.loan-stats article:last-child strong { margin: 0; }.loan-status { padding: 5px; font-size: 10px; }header { padding: 14px; }.source-note { font-size: 11px; } }
</style>
